import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Arc Standard Library Reference","description":"","frontmatter":{},"headers":[],"relativePath":"stdlib-reference.md","filePath":"stdlib-reference.md"}'),s={name:"stdlib-reference.md"};function n(r,t,c,i,l,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="arc-standard-library-reference" tabindex="-1">Arc Standard Library Reference <a class="header-anchor" href="#arc-standard-library-reference" aria-label="Permalink to &quot;Arc Standard Library Reference&quot;">​</a></h1><p>Complete API reference for all Arc standard library modules.</p><blockquote><p>All 27 stdlib modules are implemented and tested. The 8 modules requiring native runtime access (regex, datetime, os, io, http, crypto, error, net) all have full native implementations backed by real system calls. 4 AI-native modules (prompt, embed, llm, store) provide first-class support for agent workflows. 6 utility modules (yaml, toml, html, path, env, log) round out the standard library.</p></blockquote><hr><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#math">math</a> ✅</li><li><a href="#strings">strings</a> ✅</li><li><a href="#collections">collections</a> ✅</li><li><a href="#map">map</a> ✅</li><li><a href="#io">io</a> ✅ Native</li><li><a href="#http">http</a> ✅ Native</li><li><a href="#json">json</a> ✅</li><li><a href="#csv">csv</a> ✅</li><li><a href="#test">test</a> ✅</li><li><a href="#result">result</a> ✅</li><li><a href="#time">time</a> ✅</li><li><a href="#regex">regex</a> ✅ Native</li><li><a href="#datetime">datetime</a> ✅ Native</li><li><a href="#os">os</a> ✅ Native</li><li><a href="#error">error</a> ✅ Native</li><li><a href="#net">net</a> ✅ Native</li><li><a href="#crypto">crypto</a> ✅ Native</li><li><a href="#prompt">prompt</a> ✅ AI-Native</li><li><a href="#embed">embed</a> ✅ AI-Native</li><li><a href="#llm">llm</a> ✅ AI-Native</li><li><a href="#store">store</a> ✅ AI-Native</li><li><a href="#yaml">yaml</a> ✅</li><li><a href="#toml">toml</a> ✅</li><li><a href="#html">html</a> ✅</li><li><a href="#path">path</a> ✅</li><li><a href="#env">env</a> ✅</li><li><a href="#log">log</a> ✅</li></ul><hr><h2 id="math" tabindex="-1">math <a class="header-anchor" href="#math" aria-label="Permalink to &quot;math&quot;">​</a></h2><p>Mathematical constants and functions.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use math</span></span></code></pre></div><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>PI</code></td><td><code>3.141592653589793</code></td><td>Ratio of circle&#39;s circumference to diameter</td></tr><tr><td><code>E</code></td><td><code>2.718281828459045</code></td><td>Euler&#39;s number</td></tr><tr><td><code>TAU</code></td><td><code>6.283185307179586</code></td><td>2π — full circle in radians</td></tr></tbody></table><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>abs</code></td><td><code>(x) -&gt; Number</code></td><td>Absolute value</td></tr><tr><td><code>sign</code></td><td><code>(x) -&gt; Number</code></td><td>Sign of number (-1, 0, or 1)</td></tr><tr><td><code>clamp</code></td><td><code>(x, lo, hi) -&gt; Number</code></td><td>Constrain to range [lo, hi]</td></tr><tr><td><code>ceil</code></td><td><code>(x) -&gt; Int</code></td><td>Smallest integer ≥ x</td></tr><tr><td><code>floor</code></td><td><code>(x) -&gt; Int</code></td><td>Largest integer ≤ x</td></tr><tr><td><code>round</code></td><td><code>(x) -&gt; Int</code></td><td>Round to nearest integer</td></tr><tr><td><code>pow</code></td><td><code>(base, exp) -&gt; Number</code></td><td>Raise base to power</td></tr><tr><td><code>sqrt</code></td><td><code>(x) -&gt; Number | nil</code></td><td>Square root (nil for negative)</td></tr><tr><td><code>cbrt</code></td><td><code>(x) -&gt; Number</code></td><td>Cube root</td></tr><tr><td><code>hypot</code></td><td><code>(a, b) -&gt; Number</code></td><td>Hypotenuse (√(a²+b²))</td></tr><tr><td><code>sin</code></td><td><code>(x) -&gt; Number</code></td><td>Sine (radians)</td></tr><tr><td><code>cos</code></td><td><code>(x) -&gt; Number</code></td><td>Cosine (radians)</td></tr><tr><td><code>tan</code></td><td><code>(x) -&gt; Number</code></td><td>Tangent (radians)</td></tr><tr><td><code>asin</code></td><td><code>(x) -&gt; Number</code></td><td>Arcsine</td></tr><tr><td><code>acos</code></td><td><code>(x) -&gt; Number</code></td><td>Arccosine</td></tr><tr><td><code>atan</code></td><td><code>(x) -&gt; Number</code></td><td>Arctangent</td></tr><tr><td><code>atan2</code></td><td><code>(y, x) -&gt; Number</code></td><td>Two-argument arctangent</td></tr><tr><td><code>degrees</code></td><td><code>(radians) -&gt; Number</code></td><td>Convert radians to degrees</td></tr><tr><td><code>radians</code></td><td><code>(degrees) -&gt; Number</code></td><td>Convert degrees to radians</td></tr><tr><td><code>log</code></td><td><code>(x) -&gt; Number</code></td><td>Natural logarithm</td></tr><tr><td><code>log2</code></td><td><code>(x) -&gt; Number</code></td><td>Base-2 logarithm</td></tr><tr><td><code>log10</code></td><td><code>(x) -&gt; Number</code></td><td>Base-10 logarithm</td></tr><tr><td><code>exp</code></td><td><code>(x) -&gt; Number</code></td><td>e^x</td></tr><tr><td><code>factorial</code></td><td><code>(n) -&gt; Int</code></td><td>Factorial</td></tr><tr><td><code>gcd</code></td><td><code>(a, b) -&gt; Int</code></td><td>Greatest common divisor</td></tr><tr><td><code>lcm</code></td><td><code>(a, b) -&gt; Int</code></td><td>Least common multiple</td></tr><tr><td><code>sum</code></td><td><code>(list) -&gt; Number</code></td><td>Sum of a list</td></tr><tr><td><code>product</code></td><td><code>(list) -&gt; Number</code></td><td>Product of a list</td></tr></tbody></table><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>math.abs(-5)       # =&gt; 5</span></span>
<span class="line"><span>math.pow(2, 10)    # =&gt; 1024</span></span>
<span class="line"><span>math.sqrt(144)     # =&gt; 12</span></span>
<span class="line"><span>math.round(4.6)    # =&gt; 5</span></span>
<span class="line"><span>math.sin(math.PI)  # =&gt; ~0</span></span>
<span class="line"><span>math.sum([1,2,3])  # =&gt; 6</span></span></code></pre></div><hr><h2 id="strings" tabindex="-1">strings <a class="header-anchor" href="#strings" aria-label="Permalink to &quot;strings&quot;">​</a></h2><p>String manipulation utilities beyond the built-in string functions.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use strings</span></span></code></pre></div><h3 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><h4 id="pad-left-s-width-ch-string" tabindex="-1"><code>pad_left(s, width, ch) -&gt; String</code> <a class="header-anchor" href="#pad-left-s-width-ch-string" aria-label="Permalink to &quot;\`pad_left(s, width, ch) -&gt; String\`&quot;">​</a></h4><p>Pads string <code>s</code> on the left with character <code>ch</code> until it reaches <code>width</code>.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strings.pad_left(&quot;42&quot;, 5, &quot;0&quot;)    # =&gt; &quot;00042&quot;</span></span>
<span class="line"><span>strings.pad_left(&quot;hello&quot;, 3, &quot; &quot;) # =&gt; &quot;hello&quot;  (already &gt;= width)</span></span></code></pre></div><h4 id="pad-right-s-width-ch-string" tabindex="-1"><code>pad_right(s, width, ch) -&gt; String</code> <a class="header-anchor" href="#pad-right-s-width-ch-string" aria-label="Permalink to &quot;\`pad_right(s, width, ch) -&gt; String\`&quot;">​</a></h4><p>Pads string <code>s</code> on the right with character <code>ch</code> until it reaches <code>width</code>.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strings.pad_right(&quot;hi&quot;, 5, &quot;.&quot;)   # =&gt; &quot;hi...&quot;</span></span></code></pre></div><h4 id="capitalize-s-string" tabindex="-1"><code>capitalize(s) -&gt; String</code> <a class="header-anchor" href="#capitalize-s-string" aria-label="Permalink to &quot;\`capitalize(s) -&gt; String\`&quot;">​</a></h4><p>Capitalizes the first letter and lowercases the rest.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strings.capitalize(&quot;hello&quot;)   # =&gt; &quot;Hello&quot;</span></span>
<span class="line"><span>strings.capitalize(&quot;aRC&quot;)     # =&gt; &quot;Arc&quot;</span></span>
<span class="line"><span>strings.capitalize(&quot;&quot;)        # =&gt; &quot;&quot;</span></span></code></pre></div><h4 id="words-s-string" tabindex="-1"><code>words(s) -&gt; [String]</code> <a class="header-anchor" href="#words-s-string" aria-label="Permalink to &quot;\`words(s) -&gt; [String]\`&quot;">​</a></h4><p>Splits a string into a list of words (split by spaces, trimmed, empty strings removed).</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strings.words(&quot;  hello   world  &quot;)  # =&gt; [&quot;hello&quot;, &quot;world&quot;]</span></span></code></pre></div><hr><h2 id="collections" tabindex="-1">collections <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;collections&quot;">​</a></h2><p>List, set, and queue utilities.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use collections</span></span></code></pre></div><h3 id="functions-2" tabindex="-1">Functions <a class="header-anchor" href="#functions-2" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>set</code></td><td><code>(list) -&gt; [Any]</code></td><td>Remove duplicates (returns deduplicated list)</td></tr><tr><td><code>unique</code></td><td><code>(list) -&gt; [Any]</code></td><td>Alias for <code>set</code></td></tr><tr><td><code>group_by</code></td><td><code>(list, fn) -&gt; Map</code></td><td>Group elements by key function</td></tr><tr><td><code>count_by</code></td><td><code>(list, fn) -&gt; Map</code></td><td>Count elements by key function</td></tr><tr><td><code>chunk</code></td><td><code>(list, size) -&gt; [[Any]]</code></td><td>Split list into chunks</td></tr><tr><td><code>flatten</code></td><td><code>(nested) -&gt; [Any]</code></td><td>Flatten nested lists one level</td></tr><tr><td><code>zip_with</code></td><td><code>(a, b, fn) -&gt; [Any]</code></td><td>Combine two lists element-wise with a function</td></tr><tr><td><code>partition</code></td><td><code>(list, fn) -&gt; [[Any], [Any]]</code></td><td>Split list into [matches, non-matches]</td></tr><tr><td><code>frequencies</code></td><td><code>(list) -&gt; Map</code></td><td>Count occurrences of each element</td></tr><tr><td><code>min_by</code></td><td><code>(list, fn) -&gt; Any</code></td><td>Minimum element by key function</td></tr><tr><td><code>max_by</code></td><td><code>(list, fn) -&gt; Any</code></td><td>Maximum element by key function</td></tr><tr><td><code>sort_by</code></td><td><code>(list, fn) -&gt; [Any]</code></td><td>Sort by key function</td></tr><tr><td><code>index_of</code></td><td><code>(list, val) -&gt; Int | nil</code></td><td>Index of first occurrence</td></tr><tr><td><code>includes</code></td><td><code>(list, val) -&gt; Bool</code></td><td>Check if list contains value</td></tr></tbody></table><blockquote><p>Built-in list functions (<code>map</code>, <code>filter</code>, <code>reduce</code>, <code>take</code>, <code>skip</code>, <code>find</code>, <code>contains</code>, <code>len</code>, <code>push</code>, <code>concat</code>) are available without <code>use</code>.</p></blockquote><hr><h2 id="map" tabindex="-1">map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;map&quot;">​</a></h2><p>Map/dictionary utilities.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use map</span></span></code></pre></div><h3 id="functions-3" tabindex="-1">Functions <a class="header-anchor" href="#functions-3" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>merge</code></td><td><code>(a, b) -&gt; Map</code></td><td>Merge two maps (b overwrites a)</td></tr><tr><td><code>map_values</code></td><td><code>(m, fn) -&gt; Map</code></td><td>Transform all values</td></tr><tr><td><code>map_keys</code></td><td><code>(m, fn) -&gt; Map</code></td><td>Transform all keys</td></tr><tr><td><code>filter_map</code></td><td><code>(m, fn) -&gt; Map</code></td><td>Filter entries by predicate</td></tr><tr><td><code>from_pairs</code></td><td><code>(pairs) -&gt; Map</code></td><td>Create map from key-value pairs</td></tr><tr><td><code>to_pairs</code></td><td><code>(m) -&gt; [(Any, Any)]</code></td><td>Convert map to key-value pairs</td></tr><tr><td><code>pick</code></td><td><code>(m, keys) -&gt; Map</code></td><td>Select only specified keys</td></tr><tr><td><code>omit</code></td><td><code>(m, keys) -&gt; Map</code></td><td>Remove specified keys</td></tr></tbody></table><blockquote><p>Built-in <code>keys(m)</code>, <code>values(m)</code> are available without <code>use</code>.</p></blockquote><hr><h2 id="io" tabindex="-1">io <a class="header-anchor" href="#io" aria-label="Permalink to &quot;io&quot;">​</a></h2><p>File and console I/O with native Node.js fs implementation.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use io</span></span></code></pre></div><h3 id="functions-4" tabindex="-1">Functions <a class="header-anchor" href="#functions-4" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>read_file</code></td><td><code>(path) -&gt; Result&lt;String&gt;</code></td><td>Read file contents</td></tr><tr><td><code>write_file</code></td><td><code>(path, content) -&gt; Result&lt;nil&gt;</code></td><td>Write string to file</td></tr><tr><td><code>read_lines</code></td><td><code>(path) -&gt; Result&lt;[String]&gt;</code></td><td>Read file as lines</td></tr><tr><td><code>write_lines</code></td><td><code>(path, lines) -&gt; Result&lt;nil&gt;</code></td><td>Write list of lines to file</td></tr><tr><td><code>exists</code></td><td><code>(path) -&gt; Bool</code></td><td>Check if path exists</td></tr><tr><td><code>append</code></td><td><code>(path, content) -&gt; Result&lt;nil&gt;</code></td><td>Append string to file</td></tr></tbody></table><blockquote><p><code>print(...)</code> is a built-in and does not require import.</p></blockquote><hr><h2 id="http" tabindex="-1">http <a class="header-anchor" href="#http" aria-label="Permalink to &quot;http&quot;">​</a></h2><p>HTTP client with native fetch implementation via sync bridge.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use http</span></span></code></pre></div><h3 id="functions-5" tabindex="-1">Functions <a class="header-anchor" href="#functions-5" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>get</code></td><td><code>(url, headers?) -&gt; Result&lt;Response&gt;</code></td><td>HTTP GET</td></tr><tr><td><code>post</code></td><td><code>(url, body, headers?) -&gt; Result&lt;Response&gt;</code></td><td>HTTP POST</td></tr><tr><td><code>put</code></td><td><code>(url, body, headers?) -&gt; Result&lt;Response&gt;</code></td><td>HTTP PUT</td></tr><tr><td><code>delete</code></td><td><code>(url, headers?) -&gt; Result&lt;Response&gt;</code></td><td>HTTP DELETE</td></tr><tr><td><code>fetch_all</code></td><td><code>(requests) -&gt; [Result&lt;Response&gt;]</code></td><td>Execute multiple HTTP requests</td></tr><tr><td><code>parse_url</code></td><td><code>(url) -&gt; Map</code></td><td>Parse URL into components</td></tr></tbody></table><blockquote><p>Arc also supports the <code>@GET</code>, <code>@POST</code> syntax for inline HTTP calls — see the <a href="/language-tour">Language Tour</a>.</p></blockquote><hr><h2 id="json" tabindex="-1">json <a class="header-anchor" href="#json" aria-label="Permalink to &quot;json&quot;">​</a></h2><p>JSON serialization and deserialization.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use json</span></span></code></pre></div><h3 id="functions-6" tabindex="-1">Functions <a class="header-anchor" href="#functions-6" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>from_json</code></td><td><code>(s: String) -&gt; Result&lt;Any&gt;</code></td><td>Parse JSON string to Arc value</td></tr><tr><td><code>to_json</code></td><td><code>(value, indent?) -&gt; String</code></td><td>Convert Arc value to JSON string</td></tr><tr><td><code>pretty</code></td><td><code>(value) -&gt; String</code></td><td>Pretty-print with 2-space indent</td></tr><tr><td><code>get_path</code></td><td><code>(value, path) -&gt; Any</code></td><td>Get nested value by dot-separated path</td></tr></tbody></table><hr><h2 id="csv" tabindex="-1">csv <a class="header-anchor" href="#csv" aria-label="Permalink to &quot;csv&quot;">​</a></h2><p>CSV parsing and generation.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use csv</span></span></code></pre></div><h3 id="functions-7" tabindex="-1">Functions <a class="header-anchor" href="#functions-7" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>parse_csv</code></td><td><code>(s: String, sep?) -&gt; [[String]]</code></td><td>Parse CSV to rows</td></tr><tr><td><code>parse_csv_headers</code></td><td><code>(s: String, sep?) -&gt; [Map]</code></td><td>Parse CSV with header row to maps</td></tr><tr><td><code>to_csv</code></td><td><code>(rows: [[String]], sep?) -&gt; String</code></td><td>Convert rows to CSV string</td></tr></tbody></table><hr><h2 id="test" tabindex="-1">test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;test&quot;">​</a></h2><p>Testing framework.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use test</span></span></code></pre></div><h3 id="functions-8" tabindex="-1">Functions <a class="header-anchor" href="#functions-8" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>describe</code></td><td><code>(name, fn)</code></td><td>Define a test suite</td></tr><tr><td><code>it</code></td><td><code>(name, fn)</code></td><td>Define a test case</td></tr><tr><td><code>expect_eq</code></td><td><code>(a, b)</code></td><td>Assert equality</td></tr><tr><td><code>expect_neq</code></td><td><code>(a, b)</code></td><td>Assert inequality</td></tr><tr><td><code>expect_true</code></td><td><code>(cond)</code></td><td>Assert truthy</td></tr><tr><td><code>expect_false</code></td><td><code>(cond)</code></td><td>Assert falsy</td></tr><tr><td><code>expect_nil</code></td><td><code>(val)</code></td><td>Assert nil</td></tr><tr><td><code>expect_gt</code></td><td><code>(a, b)</code></td><td>Assert a &gt; b</td></tr><tr><td><code>expect_lt</code></td><td><code>(a, b)</code></td><td>Assert a &lt; b</td></tr><tr><td><code>run_tests</code></td><td><code>()</code></td><td>Run all defined test suites</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use test</span></span>
<span class="line"><span></span></span>
<span class="line"><span>test.describe(&quot;math&quot;, fn() {</span></span>
<span class="line"><span>  test.it(&quot;adds numbers&quot;, fn() {</span></span>
<span class="line"><span>    test.expect_eq(1 + 1, 2)</span></span>
<span class="line"><span>  })</span></span>
<span class="line"><span>  test.it(&quot;strings are non-empty&quot;, fn() {</span></span>
<span class="line"><span>    test.expect_true(len(&quot;hello&quot;) &gt; 0)</span></span>
<span class="line"><span>  })</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>test.run_tests()</span></span></code></pre></div><hr><h2 id="result" tabindex="-1">result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;result&quot;">​</a></h2><p>Error handling with Result types.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use result</span></span></code></pre></div><p>Arc uses <code>Result&lt;T&gt;</code> as the standard error-handling pattern — either <code>Ok(value)</code> or <code>Err(message)</code>.</p><h3 id="functions-9" tabindex="-1">Functions <a class="header-anchor" href="#functions-9" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>ok</code></td><td><code>(value) -&gt; Result&lt;T&gt;</code></td><td>Wrap value in Ok</td></tr><tr><td><code>err</code></td><td><code>(msg) -&gt; Result&lt;T&gt;</code></td><td>Create an Err</td></tr><tr><td><code>is_ok</code></td><td><code>(r) -&gt; Bool</code></td><td>Check if Ok</td></tr><tr><td><code>is_err</code></td><td><code>(r) -&gt; Bool</code></td><td>Check if Err</td></tr><tr><td><code>unwrap</code></td><td><code>(r) -&gt; T</code></td><td>Get value or panic</td></tr><tr><td><code>unwrap_or</code></td><td><code>(r, default) -&gt; T</code></td><td>Get value or default</td></tr><tr><td><code>unwrap_err</code></td><td><code>(r) -&gt; String</code></td><td>Get error message or panic</td></tr><tr><td><code>map</code></td><td><code>(r, fn) -&gt; Result&lt;U&gt;</code></td><td>Transform Ok value</td></tr><tr><td><code>flat_map</code></td><td><code>(r, fn) -&gt; Result&lt;U&gt;</code></td><td>Chain Result-returning functions</td></tr><tr><td><code>try_fn</code></td><td><code>(fn) -&gt; Result&lt;T&gt;</code></td><td>Run function, catching errors as Err</td></tr><tr><td><code>result_is_ok</code></td><td><code>(r) -&gt; Bool</code></td><td>Check if Ok (alternate form)</td></tr><tr><td><code>result_is_err</code></td><td><code>(r) -&gt; Bool</code></td><td>Check if Err (alternate form)</td></tr><tr><td><code>result_unwrap</code></td><td><code>(r) -&gt; T</code></td><td>Unwrap (alternate form)</td></tr><tr><td><code>result_unwrap_or</code></td><td><code>(r, default) -&gt; T</code></td><td>Unwrap or default (alternate form)</td></tr><tr><td><code>result_map</code></td><td><code>(r, fn) -&gt; Result&lt;U&gt;</code></td><td>Map Ok value (alternate form)</td></tr><tr><td><code>flat_map_result</code></td><td><code>(r, fn) -&gt; Result&lt;U&gt;</code></td><td>Chain Results (alternate form)</td></tr></tbody></table><h3 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use result</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let r = result.ok(42)</span></span>
<span class="line"><span>let doubled = r |&gt; result.map(x =&gt; x * 2)  # Ok(84)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let e = result.err(&quot;not found&quot;)</span></span>
<span class="line"><span>result.unwrap_or(e, 0)  # =&gt; 0</span></span></code></pre></div><hr><h2 id="time" tabindex="-1">time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;time&quot;">​</a></h2><p>Date, time, and duration utilities.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use time</span></span></code></pre></div><h3 id="functions-10" tabindex="-1">Functions <a class="header-anchor" href="#functions-10" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>now</code></td><td><code>() -&gt; Timestamp</code></td><td>Current Unix timestamp (ms)</td></tr><tr><td><code>format_duration</code></td><td><code>(ms) -&gt; String</code></td><td>Format milliseconds as human-readable duration</td></tr><tr><td><code>sleep</code></td><td><code>(ms)</code></td><td>Pause execution</td></tr></tbody></table><hr><h2 id="built-in-functions-no-use-required" tabindex="-1">Built-in Functions (No <code>use</code> Required) <a class="header-anchor" href="#built-in-functions-no-use-required" aria-label="Permalink to &quot;Built-in Functions (No \`use\` Required)&quot;">​</a></h2><p>These are available globally in every Arc program:</p><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>print(...)</code></td><td>Print to stdout</td></tr><tr><td><code>len(x)</code></td><td>Length of string, list, or map</td></tr><tr><td><code>str(x)</code></td><td>Convert to string</td></tr><tr><td><code>int(x)</code></td><td>Convert to integer</td></tr><tr><td><code>float(x)</code></td><td>Convert to float</td></tr><tr><td><code>type(x)</code></td><td>Get type name as string</td></tr><tr><td><code>split(s, sep)</code></td><td>Split string by separator</td></tr><tr><td><code>join(list, sep)</code></td><td>Join list into string</td></tr><tr><td><code>trim(s)</code></td><td>Trim whitespace</td></tr><tr><td><code>upper(s)</code></td><td>Uppercase string</td></tr><tr><td><code>lower(s)</code></td><td>Lowercase string</td></tr><tr><td><code>slice(x, start, end)</code></td><td>Slice string or list</td></tr><tr><td><code>map(list, fn)</code></td><td>Transform each element</td></tr><tr><td><code>filter(list, fn)</code></td><td>Keep matching elements</td></tr><tr><td><code>reduce(list, fn, init)</code></td><td>Fold list to single value</td></tr><tr><td><code>find(list, fn)</code></td><td>Find first match</td></tr><tr><td><code>contains(list, val)</code></td><td>Check membership</td></tr><tr><td><code>push(list, val)</code></td><td>Append to list</td></tr><tr><td><code>concat(a, b)</code></td><td>Concatenate lists</td></tr><tr><td><code>take(list, n)</code></td><td>First n elements</td></tr><tr><td><code>skip(list, n)</code></td><td>Skip first n elements</td></tr><tr><td><code>sort(list)</code></td><td>Sort list</td></tr><tr><td><code>reverse(list)</code></td><td>Reverse list</td></tr><tr><td><code>keys(map)</code></td><td>Map keys</td></tr><tr><td><code>values(map)</code></td><td>Map values</td></tr></tbody></table><hr><h2 id="regex" tabindex="-1">regex <a class="header-anchor" href="#regex" aria-label="Permalink to &quot;regex&quot;">​</a></h2><p>Regular expression operations with native implementation and ReDoS protection.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use regex</span></span></code></pre></div><h3 id="functions-11" tabindex="-1">Functions <a class="header-anchor" href="#functions-11" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>find</code></td><td><code>(pattern, str) -&gt; Match | nil</code></td><td>Find first match</td></tr><tr><td><code>find_all</code></td><td><code>(pattern, str) -&gt; [Match]</code></td><td>Find all matches</td></tr><tr><td><code>match_all</code></td><td><code>(pattern, str) -&gt; [Match]</code></td><td>All matches (alias for find_all)</td></tr><tr><td><code>test</code></td><td><code>(pattern, str) -&gt; Bool</code></td><td>Test if pattern matches</td></tr><tr><td><code>replace</code></td><td><code>(pattern, str, replacement) -&gt; String</code></td><td>Replace first match</td></tr><tr><td><code>replace_first</code></td><td><code>(pattern, str, replacement) -&gt; String</code></td><td>Replace first match</td></tr><tr><td><code>replace_all</code></td><td><code>(pattern, str, replacement) -&gt; String</code></td><td>Replace all matches</td></tr><tr><td><code>split</code></td><td><code>(pattern, str) -&gt; [String]</code></td><td>Split by pattern</td></tr><tr><td><code>capture</code></td><td><code>(pattern, str) -&gt; [String] | nil</code></td><td>Capture groups from first match</td></tr><tr><td><code>capture_all</code></td><td><code>(pattern, str) -&gt; [[String]]</code></td><td>All capture groups</td></tr><tr><td><code>escape</code></td><td><code>(str) -&gt; String</code></td><td>Escape regex metacharacters</td></tr><tr><td><code>is_valid</code></td><td><code>(pattern) -&gt; Bool</code></td><td>Check if pattern is valid regex</td></tr></tbody></table><hr><h2 id="datetime" tabindex="-1">datetime <a class="header-anchor" href="#datetime" aria-label="Permalink to &quot;datetime&quot;">​</a></h2><p>Date and time operations with native implementation.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use datetime</span></span></code></pre></div><h3 id="functions-12" tabindex="-1">Functions <a class="header-anchor" href="#functions-12" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>now</code></td><td><code>() -&gt; Number</code></td><td>Current Unix timestamp (milliseconds)</td></tr><tr><td><code>today</code></td><td><code>() -&gt; Map</code></td><td>Current date as <code>{year, month, day, hour, minute, second, ms}</code></td></tr><tr><td><code>parse</code></td><td><code>(str) -&gt; Timestamp</code></td><td>Parse date string</td></tr><tr><td><code>format</code></td><td><code>(ts, fmt) -&gt; String</code></td><td>Format timestamp</td></tr><tr><td><code>add_days</code></td><td><code>(ts, days) -&gt; Timestamp</code></td><td>Add days to timestamp</td></tr><tr><td><code>add_hours</code></td><td><code>(ts, hours) -&gt; Timestamp</code></td><td>Add hours to timestamp</td></tr><tr><td><code>add_minutes</code></td><td><code>(ts, minutes) -&gt; Timestamp</code></td><td>Add minutes to timestamp</td></tr><tr><td><code>diff_days</code></td><td><code>(a, b) -&gt; Number</code></td><td>Days between two timestamps</td></tr><tr><td><code>diff_hours</code></td><td><code>(a, b) -&gt; Number</code></td><td>Hours between two timestamps</td></tr><tr><td><code>diff_minutes</code></td><td><code>(a, b) -&gt; Number</code></td><td>Minutes between two timestamps</td></tr><tr><td><code>day_of_week</code></td><td><code>(ts) -&gt; String</code></td><td>Day of week name</td></tr><tr><td><code>is_before</code></td><td><code>(a, b) -&gt; Bool</code></td><td>Check if timestamp a is before b</td></tr><tr><td><code>is_after</code></td><td><code>(a, b) -&gt; Bool</code></td><td>Check if timestamp a is after b</td></tr><tr><td><code>to_iso</code></td><td><code>(ts) -&gt; String</code></td><td>Convert timestamp to ISO 8601 string</td></tr><tr><td><code>from_iso</code></td><td><code>(str) -&gt; Timestamp</code></td><td>Parse ISO 8601 string to timestamp</td></tr></tbody></table><hr><h2 id="os" tabindex="-1">os <a class="header-anchor" href="#os" aria-label="Permalink to &quot;os&quot;">​</a></h2><p>Operating system interaction with native implementation. Includes command injection protection.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use os</span></span></code></pre></div><h3 id="functions-13" tabindex="-1">Functions <a class="header-anchor" href="#functions-13" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>cwd</code></td><td><code>() -&gt; String</code></td><td>Current working directory</td></tr><tr><td><code>get_env</code></td><td><code>(name) -&gt; String | nil</code></td><td>Get environment variable</td></tr><tr><td><code>env</code></td><td><code>(name) -&gt; String | nil</code></td><td>Get environment variable (alias)</td></tr><tr><td><code>set_env</code></td><td><code>(name, value) -&gt; nil</code></td><td>Set environment variable</td></tr><tr><td><code>list_dir</code></td><td><code>(path) -&gt; [String]</code></td><td>List directory contents</td></tr><tr><td><code>is_file</code></td><td><code>(path) -&gt; Bool</code></td><td>Check if path is a file</td></tr><tr><td><code>is_dir</code></td><td><code>(path) -&gt; Bool</code></td><td>Check if path is a directory</td></tr><tr><td><code>mkdir</code></td><td><code>(path) -&gt; nil</code></td><td>Create directory</td></tr><tr><td><code>rmdir</code></td><td><code>(path) -&gt; nil</code></td><td>Remove directory</td></tr><tr><td><code>remove</code></td><td><code>(path) -&gt; nil</code></td><td>Remove file</td></tr><tr><td><code>rename</code></td><td><code>(from, to) -&gt; nil</code></td><td>Rename/move file</td></tr><tr><td><code>copy</code></td><td><code>(src, dst) -&gt; nil</code></td><td>Copy file</td></tr><tr><td><code>file_size</code></td><td><code>(path) -&gt; Int</code></td><td>Get file size in bytes</td></tr><tr><td><code>file_ext</code></td><td><code>(path) -&gt; String</code></td><td>Get file extension</td></tr><tr><td><code>join_path</code></td><td><code>(...parts) -&gt; String</code></td><td>Join path segments</td></tr><tr><td><code>parent_dir</code></td><td><code>(path) -&gt; String</code></td><td>Get parent directory</td></tr><tr><td><code>basename</code></td><td><code>(path) -&gt; String</code></td><td>Get file name from path</td></tr><tr><td><code>exec</code></td><td><code>(cmd) -&gt; Map</code></td><td>Execute shell command (10s timeout, injection-protected)</td></tr><tr><td><code>platform</code></td><td><code>() -&gt; String</code></td><td>OS platform name</td></tr><tr><td><code>home_dir</code></td><td><code>() -&gt; String</code></td><td>User home directory</td></tr><tr><td><code>temp_dir</code></td><td><code>() -&gt; String</code></td><td>Temp directory path</td></tr></tbody></table><hr><h2 id="error" tabindex="-1">error <a class="header-anchor" href="#error" aria-label="Permalink to &quot;error&quot;">​</a></h2><p>Error handling utilities with native implementation.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use error</span></span></code></pre></div><h3 id="functions-14" tabindex="-1">Functions <a class="header-anchor" href="#functions-14" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>error</code></td><td><code>(msg) -&gt; Error</code></td><td>Create an error value</td></tr><tr><td><code>is_error</code></td><td><code>(val) -&gt; Bool</code></td><td>Check if value is an error</td></tr><tr><td><code>wrap_error</code></td><td><code>(msg, cause) -&gt; Error</code></td><td>Wrap an error with additional context</td></tr><tr><td><code>try_fn</code></td><td><code>(fn) -&gt; Result</code></td><td>Run function, catching errors as Result</td></tr><tr><td><code>try_catch</code></td><td><code>(fn, handler) -&gt; Any</code></td><td>Try/catch wrapper</td></tr><tr><td><code>try_finally</code></td><td><code>(fn, cleanup) -&gt; Any</code></td><td>Try/finally wrapper</td></tr><tr><td><code>try_catch_finally</code></td><td><code>(fn, handler, cleanup) -&gt; Any</code></td><td>Try/catch/finally wrapper</td></tr><tr><td><code>throw</code></td><td><code>(msg) -&gt; never</code></td><td>Throw an error</td></tr><tr><td><code>retry</code></td><td><code>(fn, attempts) -&gt; Result</code></td><td>Retry a function on failure</td></tr></tbody></table><hr><h2 id="net" tabindex="-1">net <a class="header-anchor" href="#net" aria-label="Permalink to &quot;net&quot;">​</a></h2><p>Networking utilities with native implementation.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use net</span></span></code></pre></div><h3 id="functions-15" tabindex="-1">Functions <a class="header-anchor" href="#functions-15" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>url_parse</code></td><td><code>(url) -&gt; Map</code></td><td>Parse URL into components</td></tr><tr><td><code>url_encode</code></td><td><code>(str) -&gt; String</code></td><td>URL encode</td></tr><tr><td><code>url_decode</code></td><td><code>(str) -&gt; String</code></td><td>URL decode</td></tr><tr><td><code>parse_query</code></td><td><code>(str) -&gt; Map</code></td><td>Parse query string</td></tr><tr><td><code>build_query</code></td><td><code>(map) -&gt; String</code></td><td>Build query string from map</td></tr><tr><td><code>ip_is_valid</code></td><td><code>(str) -&gt; Bool</code></td><td>Validate IP address</td></tr></tbody></table><hr><h2 id="crypto" tabindex="-1">crypto <a class="header-anchor" href="#crypto" aria-label="Permalink to &quot;crypto&quot;">​</a></h2><p>Cryptographic operations with native implementation.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use crypto</span></span></code></pre></div><h3 id="functions-16" tabindex="-1">Functions <a class="header-anchor" href="#functions-16" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>md5</code></td><td><code>(str) -&gt; String</code></td><td>MD5 hash</td></tr><tr><td><code>sha1</code></td><td><code>(str) -&gt; String</code></td><td>SHA-1 hash</td></tr><tr><td><code>sha256</code></td><td><code>(str) -&gt; String</code></td><td>SHA-256 hash</td></tr><tr><td><code>sha512</code></td><td><code>(str) -&gt; String</code></td><td>SHA-512 hash</td></tr><tr><td><code>hmac_sha256</code></td><td><code>(key, data) -&gt; String</code></td><td>HMAC-SHA256</td></tr><tr><td><code>hmac_sha512</code></td><td><code>(key, data) -&gt; String</code></td><td>HMAC-SHA512</td></tr><tr><td><code>random_bytes</code></td><td><code>(n) -&gt; String</code></td><td>Random bytes (hex)</td></tr><tr><td><code>random_int</code></td><td><code>(min, max) -&gt; Int</code></td><td>Random integer in range</td></tr><tr><td><code>uuid</code></td><td><code>() -&gt; String</code></td><td>Generate UUID v4</td></tr><tr><td><code>base64_encode</code></td><td><code>(str) -&gt; String</code></td><td>Base64 encode</td></tr><tr><td><code>base64_decode</code></td><td><code>(str) -&gt; String</code></td><td>Base64 decode</td></tr><tr><td><code>hash_password</code></td><td><code>(password) -&gt; String</code></td><td>Hash a password</td></tr><tr><td><code>verify_password</code></td><td><code>(password, hash) -&gt; Bool</code></td><td>Verify password against hash</td></tr><tr><td><code>constant_time_eq</code></td><td><code>(a, b) -&gt; Bool</code></td><td>Constant-time string comparison</td></tr></tbody></table><hr><h2 id="prompt" tabindex="-1">prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;prompt&quot;">​</a></h2><p>Template management, token counting, and context windowing for AI agents.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use prompt</span></span></code></pre></div><h3 id="functions-17" tabindex="-1">Functions <a class="header-anchor" href="#functions-17" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>template</code></td><td><code>(tmpl, vars) -&gt; String</code></td><td>Fill <code>&lt;&lt;var&gt;&gt;</code> placeholders from a map</td></tr><tr><td><code>token_count</code></td><td><code>(text) -&gt; Int</code></td><td>Estimate token count (~4 chars/token)</td></tr><tr><td><code>token_truncate</code></td><td><code>(text, max_tokens) -&gt; String</code></td><td>Truncate text to fit token limit</td></tr><tr><td><code>context_window</code></td><td><code>(messages, max_tokens) -&gt; [Message]</code></td><td>Fit messages within token budget (keeps newest)</td></tr><tr><td><code>chunk</code></td><td><code>(text, max_tokens) -&gt; [String]</code></td><td>Split text into token-sized chunks</td></tr><tr><td><code>system_prompt</code></td><td><code>(role, instructions) -&gt; Message</code></td><td>Format a system message</td></tr><tr><td><code>user_message</code></td><td><code>(text) -&gt; Message</code></td><td>Format a user message</td></tr><tr><td><code>assistant_message</code></td><td><code>(text) -&gt; Message</code></td><td>Format an assistant message</td></tr><tr><td><code>format_chat</code></td><td><code>(messages) -&gt; String</code></td><td>Format message list into chat string</td></tr></tbody></table><h3 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use prompt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let tmpl = &quot;Hello &lt;&lt;name&gt;&gt;, you have &lt;&lt;count&gt;&gt; messages.&quot;</span></span>
<span class="line"><span>let filled = prompt.template(tmpl, {name: &quot;Alice&quot;, count: &quot;3&quot;})</span></span>
<span class="line"><span># =&gt; &quot;Hello Alice, you have 3 messages.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let tokens = prompt.token_count(filled)</span></span>
<span class="line"><span># =&gt; ~11</span></span></code></pre></div><hr><h2 id="embed" tabindex="-1">embed <a class="header-anchor" href="#embed" aria-label="Permalink to &quot;embed&quot;">​</a></h2><p>Vector embeddings, similarity search, and distance calculations.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use embed</span></span></code></pre></div><h3 id="functions-18" tabindex="-1">Functions <a class="header-anchor" href="#functions-18" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>dot_product</code></td><td><code>(vec_a, vec_b) -&gt; Number</code></td><td>Dot product of two vectors</td></tr><tr><td><code>magnitude</code></td><td><code>(vec) -&gt; Number</code></td><td>Vector magnitude (L2 norm)</td></tr><tr><td><code>cosine_similarity</code></td><td><code>(vec_a, vec_b) -&gt; Number</code></td><td>Cosine similarity (-1 to 1)</td></tr><tr><td><code>normalize</code></td><td><code>(vec) -&gt; [Number]</code></td><td>Normalize to unit vector</td></tr><tr><td><code>euclidean_distance</code></td><td><code>(vec_a, vec_b) -&gt; Number</code></td><td>Euclidean distance</td></tr><tr><td><code>centroid</code></td><td><code>(vectors) -&gt; [Number]</code></td><td>Average vector (centroid)</td></tr><tr><td><code>most_similar</code></td><td><code>(query_vec, candidates, top_k) -&gt; [{id, score}]</code></td><td>Top-k most similar vectors</td></tr><tr><td><code>chunk_and_embed</code></td><td><code>(text, chunk_size) -&gt; [{chunk, index}]</code></td><td>Split text into chunks</td></tr></tbody></table><h3 id="example-3" tabindex="-1">Example <a class="header-anchor" href="#example-3" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use embed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let a = [1.0, 0.0, 0.0]</span></span>
<span class="line"><span>let b = [0.0, 1.0, 0.0]</span></span>
<span class="line"><span>embed.cosine_similarity(a, b)  # =&gt; 0.0 (orthogonal)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let candidates = [</span></span>
<span class="line"><span>  {id: &quot;doc1&quot;, vector: [0.9, 0.1, 0.0]},</span></span>
<span class="line"><span>  {id: &quot;doc2&quot;, vector: [0.0, 0.8, 0.2]}</span></span>
<span class="line"><span>]</span></span>
<span class="line"><span>embed.most_similar(a, candidates, 1)  # =&gt; [{id: &quot;doc1&quot;, score: ~0.99}]</span></span></code></pre></div><hr><h2 id="llm" tabindex="-1">llm <a class="header-anchor" href="#llm" aria-label="Permalink to &quot;llm&quot;">​</a></h2><p>Multi-provider LLM API integration for AI agent workflows.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use llm</span></span></code></pre></div><h3 id="functions-19" tabindex="-1">Functions <a class="header-anchor" href="#functions-19" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>chat</code></td><td><code>(provider, model, messages, options?) -&gt; Result</code></td><td>Send chat completion request</td></tr><tr><td><code>complete</code></td><td><code>(provider, model, prompt, options?) -&gt; Result</code></td><td>Simple text completion</td></tr><tr><td><code>stream</code></td><td><code>(provider, model, messages, callback) -&gt; Result</code></td><td>Streaming chat (calls callback with response)</td></tr><tr><td><code>models</code></td><td><code>(provider) -&gt; [String]</code></td><td>List available models</td></tr><tr><td><code>estimate_cost</code></td><td><code>(model, input_tokens, output_tokens) -&gt; Cost</code></td><td>Estimate API cost in USD</td></tr><tr><td><code>providers</code></td><td><code>() -&gt; [Provider]</code></td><td>List supported providers</td></tr></tbody></table><p><strong>Supported providers:</strong> <code>&quot;openai&quot;</code>, <code>&quot;anthropic&quot;</code></p><h3 id="example-4" tabindex="-1">Example <a class="header-anchor" href="#example-4" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use llm</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let result = llm.chat(&quot;openai&quot;, &quot;gpt-4o&quot;, [</span></span>
<span class="line"><span>  {role: &quot;system&quot;, content: &quot;You are a helpful assistant.&quot;},</span></span>
<span class="line"><span>  {role: &quot;user&quot;, content: &quot;What is Arc?&quot;}</span></span>
<span class="line"><span>], {temperature: 0.7})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if result.ok {</span></span>
<span class="line"><span>  print(result.content)</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Estimate costs</span></span>
<span class="line"><span>let cost = llm.estimate_cost(&quot;gpt-4o&quot;, 1000, 500)</span></span>
<span class="line"><span>print(&quot;Cost: \${cost.total}&quot;)</span></span></code></pre></div><hr><h2 id="store" tabindex="-1">store <a class="header-anchor" href="#store" aria-label="Permalink to &quot;store&quot;">​</a></h2><p>Persistent JSON-backed key-value storage.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use store</span></span></code></pre></div><h3 id="functions-20" tabindex="-1">Functions <a class="header-anchor" href="#functions-20" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>(path) -&gt; Store</code></td><td>Open or create a JSON store file</td></tr><tr><td><code>get</code></td><td><code>(store, key) -&gt; Any | nil</code></td><td>Get value by key</td></tr><tr><td><code>set</code></td><td><code>(store, key, value) -&gt; nil</code></td><td>Set key-value pair</td></tr><tr><td><code>delete</code></td><td><code>(store, key) -&gt; nil</code></td><td>Delete a key</td></tr><tr><td><code>has</code></td><td><code>(store, key) -&gt; Bool</code></td><td>Check if key exists</td></tr><tr><td><code>keys</code></td><td><code>(store) -&gt; [String]</code></td><td>Get all keys</td></tr><tr><td><code>values</code></td><td><code>(store) -&gt; [Any]</code></td><td>Get all values</td></tr><tr><td><code>entries</code></td><td><code>(store) -&gt; [(String, Any)]</code></td><td>Get all key-value pairs</td></tr><tr><td><code>clear</code></td><td><code>(store) -&gt; nil</code></td><td>Remove all entries</td></tr><tr><td><code>size</code></td><td><code>(store) -&gt; Int</code></td><td>Number of entries</td></tr><tr><td><code>merge</code></td><td><code>(store, map) -&gt; nil</code></td><td>Merge a map into the store</td></tr><tr><td><code>get_or_set</code></td><td><code>(store, key, default_fn) -&gt; Any</code></td><td>Get existing or set default</td></tr></tbody></table><h3 id="example-5" tabindex="-1">Example <a class="header-anchor" href="#example-5" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use store</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let db = store.open(&quot;settings.json&quot;)</span></span>
<span class="line"><span>store.set(db, &quot;theme&quot;, &quot;dark&quot;)</span></span>
<span class="line"><span>store.set(db, &quot;lang&quot;, &quot;en&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let theme = store.get(db, &quot;theme&quot;)  # =&gt; &quot;dark&quot;</span></span>
<span class="line"><span>store.has(db, &quot;lang&quot;)               # =&gt; true</span></span>
<span class="line"><span>store.keys(db)                      # =&gt; [&quot;theme&quot;, &quot;lang&quot;]</span></span></code></pre></div><hr><h2 id="yaml" tabindex="-1">yaml <a class="header-anchor" href="#yaml" aria-label="Permalink to &quot;yaml&quot;">​</a></h2><p>YAML parsing and stringifying.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use yaml</span></span></code></pre></div><h3 id="functions-21" tabindex="-1">Functions <a class="header-anchor" href="#functions-21" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>parse</code></td><td><code>(text: String) -&gt; Any</code></td><td>Parse YAML string to Arc value</td></tr><tr><td><code>stringify</code></td><td><code>(value) -&gt; String</code></td><td>Convert Arc value to YAML string</td></tr></tbody></table><h3 id="example-6" tabindex="-1">Example <a class="header-anchor" href="#example-6" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use yaml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let data = yaml.parse(&quot;name: Alice\\nage: 30&quot;)</span></span>
<span class="line"><span># =&gt; {name: &quot;Alice&quot;, age: 30}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let text = yaml.stringify({host: &quot;localhost&quot;, port: 8080})</span></span>
<span class="line"><span># =&gt; &quot;host: localhost\\nport: 8080\\n&quot;</span></span></code></pre></div><hr><h2 id="toml" tabindex="-1">toml <a class="header-anchor" href="#toml" aria-label="Permalink to &quot;toml&quot;">​</a></h2><p>TOML parsing and stringifying.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use toml</span></span></code></pre></div><h3 id="functions-22" tabindex="-1">Functions <a class="header-anchor" href="#functions-22" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>parse</code></td><td><code>(text: String) -&gt; Any</code></td><td>Parse TOML string to Arc value</td></tr><tr><td><code>stringify</code></td><td><code>(value) -&gt; String</code></td><td>Convert Arc value to TOML string</td></tr></tbody></table><h3 id="example-7" tabindex="-1">Example <a class="header-anchor" href="#example-7" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use toml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let config = toml.parse(&quot;[server]\\nhost = \\&quot;localhost\\&quot;\\nport = 8080&quot;)</span></span>
<span class="line"><span># =&gt; {server: {host: &quot;localhost&quot;, port: 8080}}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let text = toml.stringify({title: &quot;My App&quot;, version: &quot;1.0&quot;})</span></span></code></pre></div><hr><h2 id="html" tabindex="-1">html <a class="header-anchor" href="#html" aria-label="Permalink to &quot;html&quot;">​</a></h2><p>HTML parsing and generation utilities.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use html</span></span></code></pre></div><h3 id="functions-23" tabindex="-1">Functions <a class="header-anchor" href="#functions-23" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>parse</code></td><td><code>(s: String) -&gt; Node</code></td><td>Parse HTML string into a node tree</td></tr><tr><td><code>select</code></td><td><code>(node, selector: String) -&gt; [Node]</code></td><td>Query nodes by CSS selector</td></tr><tr><td><code>text</code></td><td><code>(node) -&gt; String</code></td><td>Extract text content from a node</td></tr><tr><td><code>attr</code></td><td><code>(node, name: String) -&gt; String | nil</code></td><td>Get attribute value</td></tr><tr><td><code>create</code></td><td><code>(tag, attrs, children) -&gt; Node</code></td><td>Create an HTML node</td></tr><tr><td><code>render</code></td><td><code>(node) -&gt; String</code></td><td>Render node tree to HTML string</td></tr></tbody></table><h3 id="example-8" tabindex="-1">Example <a class="header-anchor" href="#example-8" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let doc = html.parse(&quot;&lt;div class=&#39;main&#39;&gt;&lt;p&gt;Hello&lt;/p&gt;&lt;/div&gt;&quot;)</span></span>
<span class="line"><span>let paragraphs = html.select(doc, &quot;p&quot;)</span></span>
<span class="line"><span>let content = html.text(paragraphs[0])  # =&gt; &quot;Hello&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let node = html.create(&quot;a&quot;, {href: &quot;/about&quot;}, [&quot;About Us&quot;])</span></span>
<span class="line"><span>html.render(node)  # =&gt; &quot;&lt;a href=\\&quot;/about\\&quot;&gt;About Us&lt;/a&gt;&quot;</span></span></code></pre></div><hr><h2 id="path" tabindex="-1">path <a class="header-anchor" href="#path" aria-label="Permalink to &quot;path&quot;">​</a></h2><p>Path manipulation utilities.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use path</span></span></code></pre></div><h3 id="functions-24" tabindex="-1">Functions <a class="header-anchor" href="#functions-24" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>join</code></td><td><code>(...parts) -&gt; String</code></td><td>Join path segments</td></tr><tr><td><code>dirname</code></td><td><code>(p: String) -&gt; String</code></td><td>Directory name</td></tr><tr><td><code>basename</code></td><td><code>(p: String) -&gt; String</code></td><td>File name</td></tr><tr><td><code>extname</code></td><td><code>(p: String) -&gt; String</code></td><td>File extension</td></tr><tr><td><code>resolve</code></td><td><code>(p: String) -&gt; String</code></td><td>Resolve to absolute path</td></tr><tr><td><code>normalize</code></td><td><code>(p: String) -&gt; String</code></td><td>Normalize path separators and dots</td></tr><tr><td><code>is_absolute</code></td><td><code>(p: String) -&gt; Bool</code></td><td>Check if path is absolute</td></tr><tr><td><code>sep</code></td><td><code>() -&gt; String</code></td><td>Platform path separator</td></tr></tbody></table><h3 id="example-9" tabindex="-1">Example <a class="header-anchor" href="#example-9" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use path</span></span>
<span class="line"><span></span></span>
<span class="line"><span>path.join(&quot;src&quot;, &quot;lib&quot;, &quot;utils.arc&quot;)  # =&gt; &quot;src/lib/utils.arc&quot;</span></span>
<span class="line"><span>path.dirname(&quot;/home/user/file.arc&quot;)    # =&gt; &quot;/home/user&quot;</span></span>
<span class="line"><span>path.basename(&quot;/home/user/file.arc&quot;)   # =&gt; &quot;file.arc&quot;</span></span>
<span class="line"><span>path.extname(&quot;main.arc&quot;)              # =&gt; &quot;.arc&quot;</span></span>
<span class="line"><span>path.is_absolute(&quot;/usr/bin&quot;)          # =&gt; true</span></span></code></pre></div><hr><h2 id="env" tabindex="-1">env <a class="header-anchor" href="#env" aria-label="Permalink to &quot;env&quot;">​</a></h2><p>Environment variable utilities.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use env</span></span></code></pre></div><h3 id="functions-25" tabindex="-1">Functions <a class="header-anchor" href="#functions-25" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>get</code></td><td><code>(key: String) -&gt; String | nil</code></td><td>Get environment variable</td></tr><tr><td><code>get_or</code></td><td><code>(key: String, default: String) -&gt; String</code></td><td>Get with default fallback</td></tr><tr><td><code>set</code></td><td><code>(key: String, val: String) -&gt; nil</code></td><td>Set environment variable</td></tr><tr><td><code>remove</code></td><td><code>(key: String) -&gt; nil</code></td><td>Remove environment variable</td></tr><tr><td><code>has</code></td><td><code>(key: String) -&gt; Bool</code></td><td>Check if variable exists</td></tr><tr><td><code>list</code></td><td><code>() -&gt; Map</code></td><td>Get all environment variables</td></tr><tr><td><code>require</code></td><td><code>(key: String) -&gt; String</code></td><td>Get or panic if missing</td></tr></tbody></table><h3 id="example-10" tabindex="-1">Example <a class="header-anchor" href="#example-10" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use env</span></span>
<span class="line"><span></span></span>
<span class="line"><span>env.set(&quot;APP_ENV&quot;, &quot;production&quot;)</span></span>
<span class="line"><span>let mode = env.get_or(&quot;APP_ENV&quot;, &quot;development&quot;)  # =&gt; &quot;production&quot;</span></span>
<span class="line"><span>env.has(&quot;APP_ENV&quot;)                                 # =&gt; true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let db_url = env.require(&quot;DATABASE_URL&quot;)  # panics if not set</span></span></code></pre></div><hr><h2 id="log" tabindex="-1">log <a class="header-anchor" href="#log" aria-label="Permalink to &quot;log&quot;">​</a></h2><p>Structured logging with levels and colors.</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use log</span></span></code></pre></div><h3 id="functions-26" tabindex="-1">Functions <a class="header-anchor" href="#functions-26" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>debug</code></td><td><code>(msg: String) -&gt; nil</code></td><td>Log at debug level</td></tr><tr><td><code>info</code></td><td><code>(msg: String) -&gt; nil</code></td><td>Log at info level</td></tr><tr><td><code>warn</code></td><td><code>(msg: String) -&gt; nil</code></td><td>Log at warn level</td></tr><tr><td><code>error</code></td><td><code>(msg: String) -&gt; nil</code></td><td>Log at error level</td></tr><tr><td><code>fatal</code></td><td><code>(msg: String) -&gt; never</code></td><td>Log and exit</td></tr><tr><td><code>set_level</code></td><td><code>(level: String) -&gt; nil</code></td><td>Set minimum log level</td></tr><tr><td><code>with</code></td><td><code>(fields: Map) -&gt; Logger</code></td><td>Create child logger with extra fields</td></tr><tr><td><code>json</code></td><td><code>(level, msg, fields) -&gt; nil</code></td><td>Emit structured JSON log entry</td></tr><tr><td><code>child_debug</code></td><td><code>(logger, msg) -&gt; nil</code></td><td>Log debug with child logger</td></tr><tr><td><code>child_info</code></td><td><code>(logger, msg) -&gt; nil</code></td><td>Log info with child logger</td></tr><tr><td><code>child_warn</code></td><td><code>(logger, msg) -&gt; nil</code></td><td>Log warn with child logger</td></tr><tr><td><code>child_error</code></td><td><code>(logger, msg) -&gt; nil</code></td><td>Log error with child logger</td></tr></tbody></table><h3 id="example-11" tabindex="-1">Example <a class="header-anchor" href="#example-11" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use log</span></span>
<span class="line"><span></span></span>
<span class="line"><span>log.set_level(&quot;info&quot;)</span></span>
<span class="line"><span>log.info(&quot;Server started&quot;)</span></span>
<span class="line"><span>log.warn(&quot;Disk usage high&quot;)</span></span>
<span class="line"><span>log.error(&quot;Connection failed&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let logger = log.with({service: &quot;api&quot;, version: &quot;1.0&quot;})</span></span>
<span class="line"><span>log.child_info(logger, &quot;Request received&quot;)  # Log with child logger context</span></span>
<span class="line"><span></span></span>
<span class="line"><span>log.json(&quot;info&quot;, &quot;request&quot;, {method: &quot;GET&quot;, path: &quot;/api/users&quot;, status: 200})</span></span></code></pre></div>`,216)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
